* >Natural Source Code: EODSALE
* PROGRAM: EODSALE - END OF DAY SALES SUMMARY
* DESCRIPTION: GENERATES DAILY SALES REPORT
*              BY STORE, PRODUCT CATEGORY, PAYMENT METHOD
*              UPDATES RUNNING TOTALS
* LIBRARY: RETAILCORE
* ADABAS FILES: 111 (ORDER), 112 (ORDER-LINE)
* CREATED: 2000-01-15  A. GARCIA
* MODIFIED: 2008-07-22 - ADDED CATEGORY BREAKDOWN
* MODIFIED: 2016-03-10 - ADDED PAYMENT METHOD SUMMARY
* MODIFIED: 2023-05-15 - ADDED CHANNEL ANALYSIS
* -------------------------------------------------------
DEFINE DATA
LOCAL
  1 #TODAY                (D)
  1 #YESTERDAY            (D)
*
* OVERALL COUNTERS
  1 #TOTAL-ORDERS         (N8)
  1 #TOTAL-LINES          (N8)
  1 #TOTAL-QTY            (N8)
  1 #TOTAL-REVENUE        (N13.2)
  1 #TOTAL-COST           (N13.2)
  1 #TOTAL-DISCOUNT       (N11.2)
  1 #TOTAL-TAX            (N11.2)
  1 #TOTAL-RETURNS        (N8)
  1 #RETURN-AMT           (N11.2)
  1 #NET-REVENUE          (N13.2)
  1 #AVG-ORDER            (N11.2)
*
* STORE BREAKDOWN (UP TO 50 STORES)
  1 #STORE-DATA (50)
    2 #SD-STORE-ID        (N4)
    2 #SD-ORDERS          (N6)
    2 #SD-REVENUE         (N11.2)
    2 #SD-QTY             (N6)
  1 #STORE-COUNT          (N4)
*
* CHANNEL BREAKDOWN
  1 #CHANNEL-STORE-ORDERS (N8)
  1 #CHANNEL-STORE-REV    (N13.2)
  1 #CHANNEL-WEB-ORDERS   (N8)
  1 #CHANNEL-WEB-REV      (N13.2)
  1 #CHANNEL-PHONE-ORDERS (N8)
  1 #CHANNEL-PHONE-REV    (N13.2)
  1 #CHANNEL-MAIL-ORDERS  (N8)
  1 #CHANNEL-MAIL-REV     (N13.2)
*
  1 ESO-VIEW VIEW OF ORDER-FILE
    2 ESO-ID               (N10)
    2 ESO-STATUS           (A3)
    2 ESO-TYPE             (A2)
    2 ESO-STORE-ID         (N4)
    2 ESO-DATE             (D)
    2 ESO-NUM-LINES        (N3)
    2 ESO-TOTAL-QTY        (N6)
    2 ESO-SUBTOTAL         (N11.2)
    2 ESO-DISCOUNT-AMT     (N9.2)
    2 ESO-TAX-AMT          (N9.2)
    2 ESO-TOTAL-AMT        (N11.2)
*
  1 ERT-VIEW VIEW OF RETURN-FILE
    2 ERT-DATE             (D)
    2 ERT-STATUS           (A3)
    2 ERT-TOTAL-AMT        (N11.2)
END-DEFINE
*
MOVE *DATX TO #TODAY
MOVE #TODAY TO #YESTERDAY
SUBTRACT 1 FROM #YESTERDAY (D)
*
* -------------------------------------------------------
* LOAD BATCH CONFIGURATION
* -------------------------------------------------------
1 #CONFIG-VALUE         (A80)
1 #CONFIG-NUM           (N11.2)
1 #CONFIG-DATE          (D)
1 #CONFIG-FLAG          (A1)
1 #CONFIG-FOUND         (A1)
1 #MIN-ORDER-THRESHOLD  (N11.2) INIT <0>
1 #REPORT-FORMAT        (A80)
*
CALLNAT 'CONFIGN' 'BATCH.SALES.MIN.AMT'
  #CONFIG-VALUE #CONFIG-NUM #CONFIG-DATE #CONFIG-FLAG #CONFIG-FOUND
IF #CONFIG-FOUND = 'Y'
  MOVE #CONFIG-NUM TO #MIN-ORDER-THRESHOLD
END-IF
*
CALLNAT 'CONFIGN' 'BATCH.LOG.LEVEL'
  #CONFIG-VALUE #CONFIG-NUM #CONFIG-DATE #CONFIG-FLAG #CONFIG-FOUND
*
* VALIDATE REPORT DATE
1 #DATE-VALID   (A1)
1 #DATE-ERR     (A60)
1 #DATE-RESULT  (D)
1 #DATE-STR     (A10)
1 #DATE-NUM     (N5)
CALLNAT 'DATEU' 'VAL' #YESTERDAY #YESTERDAY 0 #DATE-RESULT
  #DATE-STR #DATE-NUM #DATE-VALID #DATE-ERR
IF #DATE-VALID NE 'Y'
  CALLNAT 'LOGERR' 700 'EODSALE: INVALID REPORT DATE'
    'E' 'EODSALE' *USER
  ESCAPE ROUTINE
END-IF
*
* FORMAT REPORT DATE
CALLNAT 'DATEU' 'FMT' #YESTERDAY #YESTERDAY 0 #DATE-RESULT
  #DATE-STR #DATE-NUM #DATE-VALID #DATE-ERR
*
* CHECK IF BUSINESS DAY
CALLNAT 'DATEU' 'BUS' #YESTERDAY #YESTERDAY 0 #DATE-RESULT
  #DATE-STR #DATE-NUM #DATE-VALID #DATE-ERR
1 #IS-BUSINESS-DAY (A1)
MOVE #DATE-VALID TO #IS-BUSINESS-DAY
*
WRITE 'RETAILCORE - DAILY SALES REPORT'
WRITE '================================'
WRITE 'REPORT DATE:' #TODAY
WRITE 'SALES DATE :' #DATE-STR
IF #IS-BUSINESS-DAY NE 'Y'
  WRITE '** NOTE: SALES DATE WAS NOT A BUSINESS DAY **'
END-IF
WRITE ' '
*
RESET #STORE-COUNT
*
* PROCESS ORDERS FOR YESTERDAY
FIND ESO-VIEW WITH ESO-DATE = #YESTERDAY
  * SKIP CANCELLED
  IF ESO-STATUS = 'CAN'
    ESCAPE TOP
  END-IF
*
  ADD 1 TO #TOTAL-ORDERS
  ADD ESO-NUM-LINES   TO #TOTAL-LINES
  ADD ESO-TOTAL-QTY   TO #TOTAL-QTY
  ADD ESO-TOTAL-AMT   TO #TOTAL-REVENUE
  ADD ESO-DISCOUNT-AMT TO #TOTAL-DISCOUNT
  ADD ESO-TAX-AMT     TO #TOTAL-TAX
*
  * CHANNEL BREAKDOWN
  DECIDE ON FIRST VALUE OF ESO-TYPE
    VALUE 'ST'
      ADD 1 TO #CHANNEL-STORE-ORDERS
      ADD ESO-TOTAL-AMT TO #CHANNEL-STORE-REV
    VALUE 'WB'
      ADD 1 TO #CHANNEL-WEB-ORDERS
      ADD ESO-TOTAL-AMT TO #CHANNEL-WEB-REV
    VALUE 'PH'
      ADD 1 TO #CHANNEL-PHONE-ORDERS
      ADD ESO-TOTAL-AMT TO #CHANNEL-PHONE-REV
    VALUE 'MO'
      ADD 1 TO #CHANNEL-MAIL-ORDERS
      ADD ESO-TOTAL-AMT TO #CHANNEL-MAIL-REV
    NONE VALUE
      IGNORE
  END-DECIDE
*
  * STORE ACCUMULATION
  IF ESO-STORE-ID > 0
    1 #SI (N4)
    1 #STORE-FOUND (A1)
    MOVE 'N' TO #STORE-FOUND
    FOR #SI = 1 TO #STORE-COUNT
      IF #STORE-DATA.#SD-STORE-ID(#SI) = ESO-STORE-ID
        ADD 1 TO #STORE-DATA.#SD-ORDERS(#SI)
        ADD ESO-TOTAL-AMT TO #STORE-DATA.#SD-REVENUE(#SI)
        ADD ESO-TOTAL-QTY TO #STORE-DATA.#SD-QTY(#SI)
        MOVE 'Y' TO #STORE-FOUND
      END-IF
    END-FOR
    IF #STORE-FOUND NE 'Y' AND #STORE-COUNT < 50
      ADD 1 TO #STORE-COUNT
      MOVE ESO-STORE-ID TO #STORE-DATA.#SD-STORE-ID(#STORE-COUNT)
      MOVE 1 TO #STORE-DATA.#SD-ORDERS(#STORE-COUNT)
      MOVE ESO-TOTAL-AMT TO #STORE-DATA.#SD-REVENUE(#STORE-COUNT)
      MOVE ESO-TOTAL-QTY TO #STORE-DATA.#SD-QTY(#STORE-COUNT)
    END-IF
  END-IF
END-FIND
*
* COUNT RETURNS
FIND ERT-VIEW WITH ERT-DATE = #YESTERDAY
  IF ERT-STATUS NE 'REJ'
    ADD 1 TO #TOTAL-RETURNS
    ADD ERT-TOTAL-AMT TO #RETURN-AMT
  END-IF
END-FIND
*
* CALCULATE
COMPUTE #NET-REVENUE = #TOTAL-REVENUE - #RETURN-AMT
IF #TOTAL-ORDERS > 0
  COMPUTE #AVG-ORDER = #TOTAL-REVENUE / #TOTAL-ORDERS
END-IF
*
* PRINT OVERALL SUMMARY
WRITE 'OVERALL SUMMARY'
WRITE '==============='
WRITE 'TOTAL ORDERS     :' #TOTAL-ORDERS
WRITE 'TOTAL LINES      :' #TOTAL-LINES
WRITE 'TOTAL ITEMS SOLD :' #TOTAL-QTY
WRITE 'GROSS REVENUE    :' #TOTAL-REVENUE
WRITE 'DISCOUNTS        :' #TOTAL-DISCOUNT
WRITE 'TAX COLLECTED    :' #TOTAL-TAX
WRITE 'RETURNS          :' #TOTAL-RETURNS
WRITE 'RETURN AMOUNT    :' #RETURN-AMT
WRITE 'NET REVENUE      :' #NET-REVENUE
WRITE 'AVG ORDER VALUE  :' #AVG-ORDER
WRITE ' '
*
* PRINT CHANNEL BREAKDOWN
WRITE 'CHANNEL BREAKDOWN'
WRITE '================='
WRITE 'STORE  - ORDERS:' #CHANNEL-STORE-ORDERS
  'REVENUE:' #CHANNEL-STORE-REV
WRITE 'WEB    - ORDERS:' #CHANNEL-WEB-ORDERS
  'REVENUE:' #CHANNEL-WEB-REV
WRITE 'PHONE  - ORDERS:' #CHANNEL-PHONE-ORDERS
  'REVENUE:' #CHANNEL-PHONE-REV
WRITE 'MAIL   - ORDERS:' #CHANNEL-MAIL-ORDERS
  'REVENUE:' #CHANNEL-MAIL-REV
WRITE ' '
*
* PRINT STORE BREAKDOWN
IF #STORE-COUNT > 0
  WRITE 'STORE BREAKDOWN'
  WRITE '==============='
  1 #SJ (N4)
  FOR #SJ = 1 TO #STORE-COUNT
    WRITE 'STORE' #STORE-DATA.#SD-STORE-ID(#SJ)
      'ORDERS:' #STORE-DATA.#SD-ORDERS(#SJ)
      'REVENUE:' #STORE-DATA.#SD-REVENUE(#SJ)
      'QTY:' #STORE-DATA.#SD-QTY(#SJ)
  END-FOR
  WRITE ' '
END-IF
*
* -------------------------------------------------------
* FORMAT CURRENCY AMOUNTS FOR DISPLAY
* -------------------------------------------------------
1 #FMT-OUTPUT (A132)
1 #FMT-INPUT  (A80)
CALLNAT 'FMTU' 'CURR' #FMT-INPUT #NET-REVENUE ' ' 0 #FMT-OUTPUT
WRITE 'FORMATTED NET REVENUE: ' #FMT-OUTPUT
*
* -------------------------------------------------------
* UPDATE CUSTOMER SPEND TOTALS FOR TOP CUSTOMERS
* -------------------------------------------------------
1 #UPD-RC      (N4)
1 #UPD-MSG     (A80)
1 #CUST-DATA-VIEW VIEW OF ORDER-FILE
  2 CD-CUST-ID    (N8)
  2 CD-TOTAL-AMT  (N11.2)
  2 CD-DATE       (D)
*
WRITE ' '
WRITE 'UPDATING CUSTOMER SPEND TOTALS...'
FIND #CUST-DATA-VIEW WITH CD-DATE = #YESTERDAY
  IF CD-CUST-ID > 0
    CALLNAT 'CUSTUPD' CD-CUST-ID 'SPND' ' ' CD-TOTAL-AMT
      ' ' 0 CD-DATE #UPD-RC #UPD-MSG
    IF #UPD-RC > 0
      CALLNAT 'LOGERR' #UPD-RC #UPD-MSG 'W' 'EODSALE' *USER
    END-IF
  END-IF
  IF *COUNTER > 10000
    ESCAPE BOTTOM
  END-IF
END-FIND
*
* -------------------------------------------------------
* UPDATE PRODUCT LAST-SOLD DATES
* -------------------------------------------------------
WRITE 'UPDATING PRODUCT LAST-SOLD DATES...'
1 #PROD-SOLD-VIEW VIEW OF ORDER-LINE-FILE
  2 PS-ORDER-ID   (N10)
  2 PS-PROD-ID    (N8)
  2 PS-STATUS     (A3)
*
1 #PROD-RC   (A1)
1 #PROD-MSG  (A60)
FIND #PROD-SOLD-VIEW WITH PS-ORDER-ID GE 0
  IF PS-STATUS NE 'CAN' AND PS-PROD-ID > 0
    CALLNAT 'PRODUPD' PS-PROD-ID ' ' ' ' 0 0 ' '
      #PROD-RC #PROD-MSG
    IF #PROD-RC NE 'Y'
      CALLNAT 'LOGERR' 701 #PROD-MSG 'W' 'EODSALE' *USER
    END-IF
  END-IF
  IF *COUNTER > 5000
    ESCAPE BOTTOM
  END-IF
END-FIND
*
* -------------------------------------------------------
* VALIDATE SKU CONSISTENCY FOR SOLD ITEMS
* -------------------------------------------------------
WRITE 'VALIDATING SKU CONSISTENCY...'
1 #SKU-CHECK-VIEW VIEW OF ORDER-LINE-FILE
  2 SC-PROD-ID    (N8)
  2 SC-SKU        (A15)
  2 SC-STATUS     (A3)
*
1 #SKV-PROD-ID    (N8)
1 #SKV-NAME       (A60)
1 #SKV-STATUS     (A1)
1 #SKV-PRICE      (N9.2)
1 #SKV-TAX        (A4)
1 #SKV-VALID      (A1)
1 #SKV-MSG        (A60)
1 #SKU-ERRORS     (N6)
*
FIND #SKU-CHECK-VIEW WITH SC-PROD-ID GE 0
  IF SC-STATUS NE 'CAN' AND SC-SKU NE ' '
    CALLNAT 'SKUVAL' SC-SKU ' ' #SKV-PROD-ID #SKV-NAME
      #SKV-STATUS #SKV-PRICE #SKV-TAX #SKV-VALID #SKV-MSG
    IF #SKV-VALID NE 'Y'
      ADD 1 TO #SKU-ERRORS
    END-IF
  END-IF
  IF *COUNTER > 2000
    ESCAPE BOTTOM
  END-IF
END-FIND
IF #SKU-ERRORS > 0
  1 #SKU-ERR-MSG (A80)
  COMPRESS 'EODSALE: ' #SKU-ERRORS ' SKU VALIDATION ERRORS'
    INTO #SKU-ERR-MSG
  CALLNAT 'LOGERR' 702 #SKU-ERR-MSG 'W' 'EODSALE' *USER
END-IF
WRITE '  SKU ERRORS FOUND:' #SKU-ERRORS
*
WRITE ' '
WRITE 'DAILY SALES REPORT COMPLETE'
*
* -------------------------------------------------------
* AUDIT AND LOG COMPLETION
* -------------------------------------------------------
CALLNAT 'AUDITN' 'ORD' 'EODSALE' 'U' 'BATCH'
  ' ' ' ' 'DAILY SALES REPORT GENERATED'
*
1 #COMPLETION-MSG (A80)
COMPRESS 'EODSALE COMPLETED: ORDERS=' #TOTAL-ORDERS
  ' REVENUE=' #TOTAL-REVENUE INTO #COMPLETION-MSG
CALLNAT 'LOGERR' 0 #COMPLETION-MSG 'I' 'EODSALE' *USER
*
END
